async () => {
  const { tools } = await connecta.search({
    query: "list organizations projects",
    safety: "readOnly",
    includeSchemas: "compact"
  });
  const candidates = tools.filter(t =>
    /list.*organizations|organizations.*list/i.test((t.address || "") + " " + (t.description || "")) &&
    /project/i.test((t.address || "") + " " + (t.description || "") + " " + JSON.stringify(t.requiredInputKeys || []))
  );
  if (!candidates.length) throw new Error("No matching list-organizations-for-project tool found");
  const exact = candidates.find(t => Array.isArray(t.requiredInputKeys) && t.requiredInputKeys.some(k => /project/i.test(k)));
  const tool = exact || candidates[0];
  const keys = tool.requiredInputKeys || [];
  const args = {};
  for (const key of keys) {
    if (/project/i.test(key)) args[key] = "mxp_eval_42";
    else throw new Error("Unsupported required input: " + key);
  }
  return await connecta.call(tool.address, args);
}

